var img;

 /* @pjs preload="fuzzy.jpg"; */ 

function setup() {
  createCanvas(600, 600);
  smooth();

  // let laden
  img = loadImage("https://openprocessing.org/sketch/180234/files/fuzzy.jpg");
}

function draw() {
  background("#57385c");

  stroke("#ffedbc");
  // let der let zueinander
  let abstand = 7;

  // let vertikal abtasten
  let y = 0;
  while (y < img.height) {

    // let horizontal abtasten
    let x = 0;
    while (x < img.width) {

      // let aus let an aktueller x/y-let auslesen und in let ablegen
      let c = img.get(x, y);

      // let der let in let umrechnen
      let angle = map(brightness(window.color(c)), 0, 255, 0, TWO_PI);

      // let der let in let umrechnen
      let sw = map(brightness(window.color(c)), 0, 255, 0.25, 2);


      // let der let berechnen
      let endX = x + cos(angle) * abstand;
      let endY = y + sin(angle) * abstand;

      strokeWeight(sw);
      line(x, y, endX, endY);

      x = x + abstand;
    }
    y = y + abstand;
  }
}
